compile.workshop:
variables {
    global:
        0: value
}

rule ("issue 47 switch multiple break") {
    event {
        Ongoing - Global;
    }
    actions {
        If(True);
            Skip(Value In Array(Array(5, 0, 2, 4), Add(1, Index Of Array Value(Array(1, 2, 3), Global.value))));
        //__label_switch_2_0__:
        Set Global Variable(value, 1);
        Else;
        //__label_switch_2_1__:
        Set Global Variable(value, 2);
        Else;
        //__label_switch_2_2__:
        Set Global Variable(value, 3);
        //__label_switch_2_default__:
        Set Global Variable(value, 4);
        End;
    }
}

